    class ExecuteChangeAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Execute the Change`;
            this.version = '1.2.0';

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` },
                { id: 5, titleKey: `briefing_title_r5`, textKey: `briefing_text_r5`, panelId: `round5Panel`, nameKey: `round_name_r5`, clockKey: `clock_r5` }
            ];

            // Numbers reference card.
            this.BUDGET_CAP = 60;          // EUR 60M transformation budget
            this.CHECKPOINT_MONTH = 9;     // board checkpoint
            this.BOARD_FLOOR = 50;         // funding survives above this at the checkpoint
            this.STARTING_SUPPORT = 78;    // stated survey support that masks resistance

            // Concept truths the math rewards.
            this.TRUE_THREAT = `status`;        // status/control loss drives the barons
            this.TRUE_MAP = `barons`;           // quiet barons are the lethal resistance
            this.TRUE_STALL = `resistance`;     // execution under-treated the hidden resistance

            // v1.2.0 calibration (declared in the EQIL run report 2026-11-11).
            // Gains convert at these yields so the teaching-note path no longer hits the 0-100 bounds;
            // losses apply in full. Capital is unchanged.
            this.YIELD = { change: 0.5, resist: 0.7, board: 0.75 };
            // Month-9 stall when the root concern was not funded in round 3.
            this.STALL = { change: -12, resist: 16, board: -8 };
            // Round 2 finds less when round 1 took the survey at face value.
            this.BLIND = 0.75;
            // Round 4 gains shrink when the division head was removed in round 3: the branch network no longer cooperates.
            this.HOSTILE = 0.75;
            // Tier lines on the composite.
            this.TIER = { landed: 82, ontrack: 58, surface: 45 };
            // A run whose funding is paused scores below the Surface Compliance line.
            this.PAUSED_CAP = 44;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    change: 34,            // changeability (low — three failed programmes)
                    resist: 72,            // hidden resistance still in the room (high)
                    capital: 60,           // political capital
                    board: 65,             // board confidence
                    month: 0,
                    budgetUsed: 0,
                    rootTreated: false,    // did they address the barons' real threat?
                    coOpted: false,        // is the Division Head an ally?
                    overloaded: false,     // did they big-bang launch?
                    fundingPaused: false,  // checkpoint outcome
                    interventions: [],
                    changeHistory: [34],
                    resistHistory: [72],
                    capitalHistory: [60],
                    boardHistory: [65],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    readiness: '',
                    dim: '',
                    gap: 0,
                    threat: '',
                    map: '',
                    listen: 50,
                    div: '',
                    interventions: [],
                    pace: '',
                    first: '',
                    spend: 0,
                    stall: '',
                    recover: '',
                    board: '',
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const rd = document.getElementById(`readinessInput`);
                const dm = document.getElementById(`dimInput`);
                const gp = document.getElementById(`gapInput`);
                if (rd) decisions.readiness = rd.value;
                if (dm) decisions.dim = dm.value;
                if (gp) decisions.gap = parseInt(gp.value, 10);
                if (!Number.isFinite(decisions.gap) || decisions.gap < 0 || decisions.gap > 60) {
                    warn(`warn_gap_range`); return false;
                }
            } else if (round === 2) {
                const th = document.getElementById(`threatInput`);
                const mp = document.getElementById(`mapInput`);
                const ls = document.getElementById(`listenInput`);
                if (th) decisions.threat = th.value;
                if (mp) decisions.map = mp.value;
                if (ls) decisions.listen = parseInt(ls.value, 10);
                if (!Number.isFinite(decisions.listen) || decisions.listen < 0 || decisions.listen > 100) {
                    warn(`warn_listen_range`); return false;
                }
            } else if (round === 3) {
                const dv = document.getElementById(`divInput`);
                if (dv) decisions.div = dv.value;
                const ids = [
                    [`intCoalition`, `coalition`], [`intIncentives`, `incentives`], [`intWins`, `wins`],
                    [`intRoot`, `root`], [`intComms`, `comms`], [`intConfront`, `confront`]
                ];
                const picked = [];
                ids.forEach(([elId, val]) => {
                    const el = document.getElementById(elId);
                    if (el && el.checked) picked.push(val);
                });
                decisions.interventions = picked;
                if (picked.length !== 3) {
                    warn(`warn_intervention_count`); return false;
                }
            } else if (round === 4) {
                const pc = document.getElementById(`paceInput`);
                const fr = document.getElementById(`firstInput`);
                const sp = document.getElementById(`spendInput`);
                if (pc) decisions.pace = pc.value;
                if (fr) decisions.first = fr.value;
                if (sp) decisions.spend = parseFloat(sp.value);
                if (!Number.isFinite(decisions.spend) || decisions.spend < 0) {
                    warn(`warn_spend_negative`); return false;
                }
                if (decisions.spend > this.BUDGET_CAP + 0.001) {
                    warn(`warn_over_budget`); return false;
                }
            } else if (round === 5) {
                const st = document.getElementById(`stallInput`);
                const rc = document.getElementById(`recoverInput`);
                const bd = document.getElementById(`boardInput`);
                const cv = document.getElementById(`convictionInput`);
                if (st) decisions.stall = st.value;
                if (rc) decisions.recover = rc.value;
                if (bd) decisions.board = bd.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let changeDelta = 0, resistDelta = 0, capitalDelta = 0, boardDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;
            const prevErrs = ds.errs || {};
            const errs = {};
            Object.keys(prevErrs).forEach((k) => { if (prevErrs[k] !== round) errs[k] = prevErrs[k]; });

            if (round === 1) {
                // Diagnose changeability. The 78% is polite compliance (Common Error 1).
                // Reading beneath the survey and naming the psychodynamic constraint is the win.
                if (d.readiness === `beneath`) { changeDelta += 8; resistDelta -= 4; boardDelta += 2; coachKey = `coach_r1_beneath`; }
                else if (d.readiness === `moderate`) { changeDelta += 3; resistDelta -= 1; coachKey = `coach_r1_moderate`; }
                else { changeDelta -= 6; resistDelta += 8; boardDelta += 4; coachKey = `coach_r1_surveytrust`; }

                if (d.dim === `psychodynamic`) { changeDelta += 7; resistDelta -= 3; coachKey = (d.readiness === `beneath`) ? `coach_r1_sharp` : coachKey; }
                else if (d.dim === `behavioural`) { changeDelta += 3; }
                else { changeDelta += 1; }

                // Pricing in a realistic stated-minus-actual gap. The truth is large (~30+).
                const gapError = Math.abs(d.gap - 32);
                if (gapError <= 8) { changeDelta += 6; resistDelta -= 4; }
                else if (d.gap < 16) { changeDelta -= 5; resistDelta += 6; coachKey = (d.readiness === `surveytrust`) ? coachKey : `coach_r1_gapsmall`; }
                else { changeDelta += 1; }

                summaryKey = (d.readiness === `beneath` && d.dim === `psychodynamic`) ? `sum_r1_good` : `sum_r1_weak`;
                if (d.readiness === 'surveytrust') errs.survey = 1;
            } else if (round === 2) {
                // Surface the hidden resistance. Name the real threat (status/control) and map the
                // quiet barons, not the noisy critics (Common Errors 4 & 5).
                if (d.threat === this.TRUE_THREAT) { resistDelta -= 14; changeDelta += 8; ds.rootTreated = false; coachKey = `coach_r2_status`; }
                else if (d.threat === `competence`) { resistDelta -= 5; changeDelta += 3; coachKey = `coach_r2_competence`; }
                else { resistDelta += 10; changeDelta -= 6; capitalDelta -= 6; coachKey = `coach_r2_irrational`; }

                if (d.map === this.TRUE_MAP) { resistDelta -= 8; changeDelta += 6; coachKey = (d.threat === this.TRUE_THREAT) ? `coach_r2_mapped` : coachKey; }
                else if (d.map === `vocal`) { resistDelta += 4; changeDelta -= 2; coachKey = `coach_r2_vocal`; }
                else { resistDelta += 2; }

                // Listening to resistance as information (vs. override) lowers resistance and builds
                // changeability; contempt hardens it (Common Error 5 / decision tree).
                if (d.listen >= 60) { resistDelta -= 6; changeDelta += 4; }
                else if (d.listen <= 25) { resistDelta += 8; changeDelta -= 4; capitalDelta -= 3; coachKey = `coach_r2_contempt`; }

                summaryKey = (d.threat === this.TRUE_THREAT && d.map === this.TRUE_MAP) ? `sum_r2_good` : `sum_r2_weak`;
                // v1.2.0: a leader who took the survey at face value looks less hard for hidden opposition.
                if (errs.survey) { if (changeDelta > 0) changeDelta = changeDelta * this.BLIND; if (resistDelta < 0) resistDelta = resistDelta * this.BLIND; }
                if (d.map === 'vocal') errs.noise = 2;
                if (d.threat === 'irrational' || d.listen <= 25) errs.contempt = 2;
            } else if (round === 3) {
                // Choose where to intervene. The Division Head move is decisive (Common Error 2);
                // the portfolio must hit the root, not just symptoms (Common Error 4).
                const picks = d.interventions || [];
                ds.interventions = picks.slice();

                ds.coOpted = false;
                switch (d.div) {
                    case `coopt`:
                        ds.coOpted = true;
                        capitalDelta += 6; resistDelta -= 12; changeDelta += 10; boardDelta += 2; coachKey = `coach_r3_coopt`; break;
                    case `remove`:
                        // Crushing informal power tells every baron who is next, so they all dig in.
                        capitalDelta -= 18; resistDelta += 20; changeDelta -= 10; boardDelta -= 4; coachKey = `coach_r3_remove`; break;
                    case `bypass`:
                        capitalDelta -= 4; resistDelta += 6; changeDelta -= 2; coachKey = `coach_r3_bypass`; break;
                }

                // Each intervention has a political cost and a changeability payoff.
                const COST = { coalition: 8, incentives: 10, wins: 6, root: 14, comms: 4, confront: 12 };
                const CHANGE = { coalition: 7, incentives: 8, wins: 9, root: 12, comms: 2, confront: -2 };
                const RESIST = { coalition: -5, incentives: -4, wins: -4, root: -14, comms: -1, confront: 6 };
                let cost = 0;
                picks.forEach((p) => {
                    cost += (COST[p] || 0);
                    changeDelta += (CHANGE[p] || 0);
                    resistDelta += (RESIST[p] || 0);
                });
                capitalDelta -= cost;

                // Treating the root threat is what actually moves the hidden resistance.
                if (picks.indexOf(`root`) !== -1) { ds.rootTreated = true; boardDelta += 3; }

                // Symptom-only intervention: comms/wins/coalition with no root and no early-status work.
                const symptomOnly = picks.indexOf(`root`) === -1 && (picks.indexOf(`comms`) !== -1 || picks.indexOf(`confront`) !== -1);
                if (symptomOnly && !ds.coOpted) {
                    changeDelta = Math.min(changeDelta, 4);
                    resistDelta += 8;
                    coachKey = `coach_r3_symptom`;
                }

                // Public confrontation of covert blockers spends capital and hardens them.
                if (picks.indexOf(`confront`) !== -1 && d.div !== `coopt`) {
                    resistDelta += 6; capitalDelta -= 4; coachKey = `coach_r3_confront`;
                }

                // Early wins without any root work look good now but do not hold (symptom risk).
                if (picks.indexOf(`wins`) !== -1 && ds.rootTreated) { changeDelta += 4; coachKey = (d.div === `coopt`) ? `coach_r3_balanced` : coachKey; }

                summaryKey = (ds.coOpted && ds.rootTreated) ? `sum_r3_good` : (d.div === `remove` ? `sum_r3_crush` : `sum_r3_weak`);
                ds.rootAtR3 = picks.indexOf('root') !== -1;
                if (d.div === 'remove') errs.remove = 3;
                if (!ds.rootAtR3) errs.symptom = 3;
            } else if (round === 4) {
                // Sequence execution to the absorptive capacity of the organisation (Common Error 3).
                ds.month = this.CHECKPOINT_MONTH;
                ds.budgetUsed = Math.round(d.spend);
                ds.overloaded = false;

                switch (d.pace) {
                    case `phased`:
                        changeDelta += 12; resistDelta -= 6; boardDelta += 4; coachKey = `coach_r4_phased`; break;
                    case `bigbang`:
                        // Overload a low-capacity org across three fronts: it snaps back.
                        ds.overloaded = true;
                        changeDelta -= 12; resistDelta += 16; capitalDelta -= 8; boardDelta -= 6; coachKey = `coach_r4_bigbang`; break;
                    case `frozen`:
                        changeDelta -= 6; resistDelta += 2; boardDelta -= 8; coachKey = `coach_r4_frozen`; break;
                }

                // What goes first earns the right to do the hard parts.
                if (d.first === `quickwin`) { changeDelta += 8; boardDelta += 6; capitalDelta += 5; }
                else if (d.first === `hardest`) { changeDelta -= 4; resistDelta += 8; capitalDelta -= 6; coachKey = `coach_r4_hardest`; }
                else if (d.first === `claims`) {
                    if (ds.overloaded) { changeDelta -= 4; resistDelta += 4; }
                    boardDelta += 2; coachKey = (d.pace === `bigbang`) ? coachKey : `coach_r4_claims`;
                }

                // Resourcing the transformation. Under-spend starves momentum; the budget is there to use.
                if (d.spend < 20) { changeDelta -= 6; boardDelta -= 4; coachKey = `coach_r4_underspend`; }
                else if (d.spend >= 25 && d.spend <= 45) { boardDelta += 3; }
                else if (d.spend > 50 && ds.overloaded) { boardDelta -= 3; capitalDelta -= 3; }

                summaryKey = (d.pace === `phased` && d.first === `quickwin`) ? `sum_r4_good` : (d.pace === `bigbang` ? `sum_r4_overload` : `sum_r4_weak`);
                if (errs.remove) { if (changeDelta > 0) changeDelta = changeDelta * this.HOSTILE; if (resistDelta < 0) resistDelta = resistDelta * this.HOSTILE; if (boardDelta > 0) boardDelta = boardDelta * this.HOSTILE; }
                if (d.pace === 'bigbang') errs.bigbang = 4;
                if (d.pace === 'frozen') errs.frozen = 4;
            } else if (round === 5) {
                // Month-9 checkpoint: recover by re-treating the root, not blaming the plan
                // (Common Error 5). Passive resistance from the barons has slowed claims digitisation.
                ds.month = this.CHECKPOINT_MONTH;

                // v1.2.0: the month-9 stall. A root concern left unfunded in round 3 resurfaces here,
                // before the recovery move is scored.
                ds.stalledHard = !ds.rootAtR3;
                if (ds.stalledHard) { changeDelta += this.STALL.change; resistDelta += this.STALL.resist; boardDelta += this.STALL.board; }

                if (d.stall === this.TRUE_STALL) { changeDelta += 8; boardDelta += 6; coachKey = `coach_r5_resistance`; }
                else if (d.stall === `plan`) { changeDelta -= 6; boardDelta -= 4; resistDelta += 4; coachKey = `coach_r5_plan`; }
                else { changeDelta -= 8; resistDelta += 10; capitalDelta -= 6; coachKey = `coach_r5_people`; }

                switch (d.recover) {
                    case `retreat`:
                        ds.rootTreated = true; resistDelta -= 16; changeDelta += 12; capitalDelta += 6; coachKey = (d.stall === this.TRUE_STALL) ? `coach_r5_recover` : coachKey; break;
                    case `moreComms`:
                        resistDelta += 6; changeDelta += 2; boardDelta -= 2; coachKey = `coach_r5_comms`; break;
                    case `enforce`:
                        resistDelta += 14; changeDelta -= 8; capitalDelta -= 10; coachKey = `coach_r5_enforce`; break;
                }

                // The board-facing case. Owning execution (not blaming the plan) protects funding.
                if (d.board === `execution`) { boardDelta += 14; changeDelta += 4; }
                else if (d.board === `blameplan`) { boardDelta -= 12; coachKey = `coach_r5_blameplan`; }
                else { boardDelta -= 6; coachKey = (d.board === `optimism`) ? `coach_r5_optimism` : coachKey; }

                // v1.2.0: conviction is held in the stance chosen. Behind the execution stance it moves the
                // board as before; behind another stance, a firmer hold costs more.
                if (d.board === 'execution') { boardDelta += Math.round((d.conviction - 60) / 8); }
                else { boardDelta -= Math.round(d.conviction / 20); }
                if (d.stall === 'plan' || d.board === 'blameplan') errs.blameplan = 5;
                if (d.recover === 'enforce') errs.enforce = 5;
            }

            // v1.2.0: gains convert at a yield, losses apply in full (see constructor).
            if (changeDelta > 0) changeDelta = changeDelta * this.YIELD.change;
            if (resistDelta < 0) resistDelta = resistDelta * this.YIELD.resist;
            if (boardDelta > 0) boardDelta = boardDelta * this.YIELD.board;
            ds.errs = errs;

            // Apply deltas with clamps.
            ds.change = Math.max(0, Math.min(100, ds.change + changeDelta));
            ds.resist = Math.max(0, Math.min(100, ds.resist + resistDelta));
            ds.capital = Math.max(0, Math.min(100, ds.capital + capitalDelta));
            ds.board = Math.max(0, Math.min(100, ds.board + boardDelta));

            // The month-9 checkpoint funding test (evaluated at rounds 4 and 5).
            if ((round === 4 || round === 5) && ds.board < this.BOARD_FLOOR) {
                ds.fundingPaused = true;
            } else if (round === 5 && ds.board >= this.BOARD_FLOOR) {
                ds.fundingPaused = false;
            }

            ds.changeHistory.push(Math.round(ds.change));
            ds.resistHistory.push(Math.round(ds.resist));
            ds.capitalHistory.push(Math.round(ds.capital));
            ds.boardHistory.push(Math.round(ds.board));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 500);

            var res = {
                period: state.currentPeriod,
                change: Math.round(ds.change),
                changeDelta: Math.round(changeDelta),
                resist: Math.round(ds.resist),
                resistDelta: Math.round(resistDelta),
                capital: Math.round(ds.capital),
                capitalDelta: Math.round(capitalDelta),
                board: Math.round(ds.board),
                boardDelta: Math.round(boardDelta),
                fundingPaused: ds.fundingPaused,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
            // Expose composite to the reporting/grading layer each period (results_utils.php reads
            // domainState.performance.overallScore); the final period locks the authoritative score.
            ds.performance = { overallScore: this._composite(ds) };
            var errRounds = {};
            Object.keys(errs).forEach(function(k) { errRounds[errs[k]] = 1; });
            ds.cleanRounds = round - Object.keys(errRounds).length;
            ds.performance.outcome = ds.performance.overallScore;
            ds.performance.process = Math.round(100 * ds.cleanRounds / round);
            // Composite per round, written by index so a replayed round overwrites its own entry.
            if (!ds.scoreHistory) ds.scoreHistory = [42];
            ds.scoreHistory[round] = ds.performance.overallScore;
            ds.scoreHistory.length = round + 1;
            return res;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);
            uiManager.bind(`changeDisplay`, `domainState.change`, (v) => Math.round(v));
            uiManager.bind(`resistDisplay`, `domainState.resist`, (v) => Math.round(v));
            uiManager.bind(`capitalDisplay`, `domainState.capital`, (v) => Math.round(v));
            uiManager.bind(`boardDisplay`, `domainState.board`, (v) => {
                const card = document.querySelector(`.execsim-card-board`);
                if (card) {
                    card.classList.toggle(`execsim-board-risk`, Number(v) < this.BOARD_FLOOR);
                    card.classList.toggle(`execsim-board-safe`, Number(v) >= this.BOARD_FLOOR);
                }
                return Math.round(v);
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                const month = window.mySimulation.state.domainState.month || 0;
                return `€` + Math.round(v) + `M / €60M · ` + window.mySimulation.t(`month_word`) + ` ` + month;
            });

            const gap = document.getElementById(`gapInput`);
            const gapReadout = document.getElementById(`gapReadout`);
            if (gap && gapReadout) {
                gapReadout.textContent = gap.value;
                gap.addEventListener(`input`, function() { gapReadout.textContent = gap.value; });
            }
            const listen = document.getElementById(`listenInput`);
            const listenReadout = document.getElementById(`listenReadout`);
            if (listen && listenReadout) {
                listenReadout.textContent = listen.value;
                listen.addEventListener(`input`, function() { listenReadout.textContent = listen.value; });
            }
        }

        getChartConfig() {
            return {
                execChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: `Changeability`,
                                data: [],
                                borderColor: `#2f80c0`,
                                backgroundColor: `rgba(47,128,192,0.15)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#2f80c0`,
                                yAxisID: `y`
                            },
                            {
                                label: `Hidden Resistance`,
                                data: [],
                                borderColor: `#b03a48`,
                                backgroundColor: `rgba(176,58,72,0.10)`,
                                borderWidth: 3,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#b03a48`,
                                yAxisID: `y`
                            },
                            {
                                label: `Political Capital`,
                                data: [],
                                borderColor: `#c7972f`,
                                backgroundColor: `rgba(199,151,47,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#c7972f`,
                                yAxisID: `y`
                            },
                            {
                                label: `Board Confidence`,
                                data: [],
                                borderColor: `#3b8f6a`,
                                backgroundColor: `rgba(59,143,106,0.08)`,
                                borderWidth: 2,
                                borderDash: [2, 3],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#3b8f6a`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#1d3557`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#5e6c83` }, grid: { color: `rgba(29,53,87,0.08)` },
                                title: { display: true, text: `0–100`, color: `#5e6c83` }
                            },
                            x: {
                                ticks: { color: `#5e6c83` }, grid: { color: `rgba(29,53,87,0.06)` },
                                title: { display: true, text: `Round`, color: `#5e6c83` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = (state && state.domainState) || {};
            const ch = ds.changeHistory || [];
            const hasT = !!(window.mySimulation && typeof window.mySimulation.t === 'function');
            const FALLBACK = { chart_start: 'Start', chart_round_short: 'R', change_label: 'Changeability', resist_label: 'Hidden Resistance', capital_label: 'Political Capital', board_label: 'Board Confidence' };
            const T = function(k) { var v = hasT ? window.mySimulation.t(k) : k; return (!v || v === k) ? FALLBACK[k] : v; };
            const labels = ch.map((_, i) => (i === 0 ? T('chart_start') : T('chart_round_short') + i));
            return {
                execChart: {
                    labels: labels,
                    datasets: [
                        { label: T('change_label'), data: ch },
                        { label: T('resist_label'), data: ds.resistHistory || [] },
                        { label: T('capital_label'), data: ds.capitalHistory || [] },
                        { label: T('board_label'), data: ds.boardHistory || [] }
                    ]
                }
            };
        }

        // Shared composite (0-100). Single source of truth for the per-period score written to
        // domainState.performance.overallScore (reporting/grading layer) AND the debrief. Weights
        // identical to v1.0.0.
        _composite(ds) {
            var change = Math.round(ds.change || 0), resist = Math.round(ds.resist || 0);
            var capital = Math.round(ds.capital || 0), board = Math.round(ds.board || 0);
            var comp = Math.max(0, Math.min(100, Math.round(change * 0.35 + (100 - resist) * 0.30 + board * 0.20 + capital * 0.15)));
            if (ds.fundingPaused) comp = Math.min(comp, this.PAUSED_CAP);
            return comp;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const change = Math.round(ds.change), resist = Math.round(ds.resist);
            const capital = Math.round(ds.capital), board = Math.round(ds.board);

            // The mandate: land the change three programmes could not land: high changeability, the
            // hidden resistance surfaced and lowered, and the funding from the board intact.
            const fundingHeld = !ds.fundingPaused && board >= this.BOARD_FLOOR;
            const resistanceBroken = resist <= 40;
            const composite = this._composite(ds);

            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };

            // Grade band -> localized label (thresholds identical to v1.0.0).
            let performanceKey = `grade_number4`;
            if (fundingHeld && resistanceBroken && change >= 65 && composite >= this.TIER.landed) performanceKey = 'grade_landed';
            else if (fundingHeld && change >= 55 && resist <= 55 && composite >= this.TIER.ontrack) performanceKey = 'grade_ontrack';
            else if (fundingHeld && composite >= this.TIER.surface) performanceKey = 'grade_surface';
            else if (!fundingHeld) performanceKey = `grade_paused`;
            const performance = T(performanceKey);

            const insights = [];
            const errs = ds.errs || {};
            if (performanceKey === 'grade_landed') insights.push(window.mySimulation.t('insight_landed'));
            else if (!fundingHeld) insights.push(window.mySimulation.t(`insight_paused`));
            else if (!resistanceBroken) insights.push(window.mySimulation.t('insight_compliance'));
            else insights.push(window.mySimulation.t('insight_close'));

            // The mistakes this run actually made, in round order (at most three are listed).
            const named = [];
            [['survey', 'err_survey'], ['contempt', 'err_contempt'], ['noise', 'err_noise'], ['remove', 'err_remove'], ['symptom', 'err_symptom'],
             ['bigbang', 'err_bigbang'], ['frozen', 'err_frozen'], ['blameplan', 'err_blameplan'], ['enforce', 'err_enforce']].forEach((p) => {
                if (errs[p[0]]) named.push({ round: errs[p[0]], key: p[1] });
            });
            // The turning point: among the rounds with a named mistake, the one where the composite moved the least.
            const sh = ds.scoreHistory || [];
            let tpRound = 0, tpMove = 1000;
            named.forEach((n) => {
                const i = n.round;
                if (typeof sh[i] !== 'number' || typeof sh[i - 1] !== 'number') return;
                const dlt = sh[i] - sh[i - 1];
                if (dlt < tpMove) { tpMove = dlt; tpRound = i; }
            });
            const turningPoint = window.mySimulation.t(tpRound ? ('tp_r' + tpRound) : 'tp_none');
            named.sort((a, b) => ((b.round === tpRound) - (a.round === tpRound)) || (a.round - b.round));
            named.slice(0, 3).sort((a, b) => a.round - b.round).forEach((n) => insights.push(window.mySimulation.t(n.key)));

            if (!ds.rootTreated && !errs.symptom) insights.push(window.mySimulation.t('insight_rootuntreated'));
            if (!ds.coOpted && !errs.remove) insights.push(window.mySimulation.t('insight_division'));
            if (capital < 30) insights.push(window.mySimulation.t(`insight_capitalspent`));
            if (performanceKey === 'grade_landed' && ds.rootTreated && ds.coOpted && named.length === 0) insights.push(window.mySimulation.t('insight_changeability'));
            const questions = [window.mySimulation.t('dq_1'), window.mySimulation.t('dq_2'), window.mySimulation.t('dq_3')];

            return {
                change: change,
                resist: resist,
                capital: capital,
                board: board,
                fundingHeld: fundingHeld,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                outcome: composite,
                process: (typeof ds.cleanRounds === 'number') ? Math.round(100 * ds.cleanRounds / Math.max(1, history.length)) : null,
                cleanRounds: (typeof ds.cleanRounds === 'number') ? ds.cleanRounds : null,
                roundsPlayed: history.length,
                turningPoint: turningPoint,
                turningPointRound: tpRound,
                questions: questions,
                insights: insights.slice(0, 5)
            };
        }

        formatCompletionMessage(summary) {
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            var s = summary || {};
            var score = (typeof s.totalScore === 'number') ? s.totalScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            var grade = s.performance || (s.performanceKey ? T(s.performanceKey) : '');
            var held = !!s.fundingHeld;
            var badge = held
                ? '<span class="ec-cm-badge ec-cm-yes">' + T('cm_fundingheld') + '</span>'
                : '<span class="ec-cm-badge ec-cm-no">' + T('cm_fundingpaused') + '</span>';
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var items = insights.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var qs = Array.isArray(s.questions) ? s.questions : [];
            var qitems = qs.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var tp = s.turningPoint ? ('<div class="ec-cm-turning"><span class="ec-cm-turning-label">' + T('cm_turning') + '</span> ' + s.turningPoint + '</div>') : '';
            var proc = (typeof s.cleanRounds === 'number') ? ('<div class="ec-cm-process"><span class="ec-cm-turning-label">' + T('cm_outcome') + '</span> ' + score + '/100 · <span class="ec-cm-turning-label">' + T('cm_process') + '</span> ' + s.cleanRounds + ' / ' + (s.roundsPlayed || 5) + '</div>') : '';
            var qblock = qitems ? ('<div class="ec-cm-insights-title">' + T('cm_questions') + '</div><ol class="ec-cm-questions">' + qitems + '</ol>') : '';
            var metrics = ''
                + '<div class="ec-cm-metric"><span class="ec-cm-mv">' + Math.round(s.change||0) + '</span><span class="ec-cm-ml">' + T('cm_m_change') + '</span></div>'
                + '<div class="ec-cm-metric"><span class="ec-cm-mv">' + Math.round(s.resist||0) + '</span><span class="ec-cm-ml">' + T('cm_m_resist') + '</span></div>'
                + '<div class="ec-cm-metric"><span class="ec-cm-mv">' + Math.round(s.board||0) + '</span><span class="ec-cm-ml">' + T('cm_m_board') + '</span></div>'
                + '<div class="ec-cm-metric"><span class="ec-cm-mv">' + Math.round(s.capital||0) + '</span><span class="ec-cm-ml">' + T('cm_m_capital') + '</span></div>';
            return ''
                + '<div class="ec-completion">'
                +   '<div class="ec-cm-head">'
                +     '<div class="ec-cm-score">' + score + '<span class="ec-cm-score-max">/100</span></div>'
                +     '<div class="ec-cm-grade">' + grade + ' ' + badge + '</div>'
                +   '</div>'
                +   '<div class="ec-cm-metrics">' + metrics + '</div>'
                +   proc
                +   tp
                +   '<div class="ec-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="ec-cm-insights">' + items + '</ul>'
                +   qblock
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.fundingPaused) return window.mySimulation.t(`hint_funding`);
            if (ds.resist >= 70) return window.mySimulation.t(`hint_resist`);
            if (ds.capital < 25) return window.mySimulation.t(`hint_capital`);
            if (!ds.rootTreated && state.currentPeriod >= 3) return window.mySimulation.t(`hint_root`);
            if (ds.change >= 60 && ds.resist <= 45 && ds.board >= this.BOARD_FLOOR) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.change`, label: `Change`, i18nKey: `col_change`, formatter: (v) => Math.round(v) },
                { key: `results.resist`, label: `Resist`, i18nKey: `col_resist`, formatter: (v) => Math.round(v) },
                { key: `results.capital`, label: `Capital`, i18nKey: `col_capital`, formatter: (v) => Math.round(v) },
                { key: `results.board`, label: `Board`, i18nKey: `col_board`, formatter: (v) => Math.round(v) }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

